import { programs, scholarships, sources, filterPrograms, checked } from './data.js';
import { notes } from './notes.js';
const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => new Intl.NumberFormat('en-US', {style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const external = (label,url) => `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
let selected = new Set();
try { selected = new Set(JSON.parse(localStorage.getItem('fieldnotes-compare') || '[]').filter(id => programs.some(p => p.id === id))); } catch {}
let query = '', area = 'All programs', awardQuery = '', awardState = 'All records', activeNote = 'README.md';
let toastTimer;
function toast(text) { $('#toast').textContent = text; $('#toast').hidden = false; clearTimeout(toastTimer); toastTimer = setTimeout(() => $('#toast').hidden = true, 2600); }
function saveSelection(){ try { localStorage.setItem('fieldnotes-compare',JSON.stringify([...selected])); } catch {} }
const head = (kicker,title,description) => `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="intro">${description}</p></div><span class="pill"><span class="dot"></span> A living research collection</span></div>`;
function programCard(p){return `<article class="program-card"><div class="card-body"><div class="card-top"><div class="school-mark ${p.color}" aria-hidden="true">${p.monogram}</div><span class="pill">${p.area}</span></div><h3>${p.short}</h3><p class="degree">${p.degree}</p><p class="card-summary">${p.summary}</p><div class="cost"><div class="cost-label"><span>${p.tuitionLabel}</span><span>${p.period}</span></div><div class="cost-number">${money(p.tuition)} <small>USD</small></div><p class="cost-note">${p.costNote}</p></div><p class="deadline"><span aria-hidden="true">◷</span> ${p.deadline}</p></div><div class="card-footer"><label class="compare-toggle"><input type="checkbox" data-compare="${p.id}" ${selected.has(p.id)?'checked':''}> Add to compare<span class="sr-only"> ${p.university}</span></label><button class="button small" data-program="${p.id}">View research <span aria-hidden="true">↗</span></button></div></article>`;}
function showPrograms(){
 $('#main').innerHTML = head('THE NEXT CHAPTER STARTS WITH A QUESTION','Where will you go next?','Explore US master’s programs in computer science and business. Compare the details that matter, with the evidence behind every finding.') + `<section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><div class="eyebrow">ONE INTAKE. DIFFERENT POSSIBILITIES.</div><h2 id="hero-title">Look beyond the ranking.<br>Understand the program.</h2><p>Costs, academic direction, internship opportunities and funding—brought together in one research space.</p><a class="text-link" href="#sources">How we research <span aria-hidden="true">↗</span></a></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit o2"></div><div class="orbit o3"></div><span class="art-year">2027</span><span class="art-caption">A WORLD OF POSSIBILITIES</span></div></section><div class="stats"><div class="stat"><strong>02</strong><div><span>Program profiles</span><small>Initial research seeds</small></div></div><div class="stat"><strong>03</strong><div><span>Funding records</span><small>Eligibility tracked separately</small></div></div><div class="stat"><strong>06</strong><div><span>Discovery sources</span><small>Plus official university pages</small></div></div></div><section aria-labelledby="programs-heading"><div class="section-row"><h2 id="programs-heading">Explore the programs</h2><span id="result-count" aria-live="polite"></span></div><div class="toolbar"><div class="tabs" aria-label="Program area">${['All programs','Computer science','Business'].map(t=>`<button data-area="${t}" aria-pressed="${area===t}">${t}</button>`).join('')}</div><label class="search"><span aria-hidden="true">⌕</span><span class="sr-only">Search programs</span><input id="program-search" type="search" placeholder="Search universities or degrees…" value="${esc(query)}"></label></div><div class="program-grid" id="program-results"></div><div class="notice"><span class="notice-icon" aria-hidden="true">ⓘ</span><div><b>Good research makes its gaps visible.</b> These are preliminary profiles, not a complete shortlist. Faculty details, ranking positions and internship outcomes still need verification. All tuition shown is a 2026–27 reference.</div></div></section><div class="bottom-grid"><section class="mini-panel"><div class="eyebrow">FUND YOUR NEXT STEP</div><h3>One scholarship. Multiple possibilities.</h3><p>Explore shared funding records, with program restrictions and application status kept in view.</p><a href="#scholarships">Browse scholarship library ↗</a></section><section class="mini-panel"><div class="eyebrow">FOLLOW THE EVIDENCE</div><h3>A broader view, from multiple sources.</h3><p>Rankings help discover programs. Official university and award pages establish the facts.</p><div class="source-strip"><span>THE</span><span>QS</span><span>U.S. News</span></div></section></div>`;
 $('#program-search').addEventListener('input',e=>{query=e.target.value;renderProgramResults();});
 renderProgramResults();
}
function renderProgramResults(){const list=filterPrograms(query,area);$('#result-count').textContent=`${list.length} of ${programs.length} profiles`;$('#program-results').innerHTML=list.length?list.map(programCard).join(''):`<div class="empty"><h2>No matching profiles yet.</h2><p>Try another search or browse all of the current research.</p><button class="button secondary" data-reset-programs>Reset filters</button></div>`;}
function showAwards(){
 $('#main').innerHTML=head('FUNDING, CONNECTED','Scholarship library','One record per opportunity, linked across relevant programs. Eligibility, deadlines and award coverage stay separate from admission decisions.')+`<div class="notice" style="margin:0 0 25px"><span class="notice-icon" aria-hidden="true">◇</span><div><b>Eligibility is not assumed.</b> Hong Kong and Taiwan requirements need separate verification. A reusable record does not mean an award can be held repeatedly or combined with other funding.</div></div><div class="toolbar"><label><span class="sr-only">Filter scholarship status</span><select class="filter-select" id="award-state">${['All records','Not marked closed','Closed'].map(s=>`<option ${s===awardState?'selected':''}>${s}</option>`).join('')}</select></label><label class="search"><span aria-hidden="true">⌕</span><span class="sr-only">Search scholarships</span><input id="award-search" type="search" placeholder="Search scholarships or institutions…" value="${esc(awardQuery)}"></label></div><div id="award-results" class="scholarship-grid" aria-live="polite"></div>`;
 $('#award-state').onchange=e=>{awardState=e.target.value;renderAwards();};$('#award-search').oninput=e=>{awardQuery=e.target.value;renderAwards();};renderAwards();
}
function renderAwards(){const list=scholarships.filter(s=>`${s.name} ${s.scope} ${s.type}`.toLowerCase().includes(awardQuery.toLowerCase())&&(awardState==='All records'||(awardState==='Closed'?s.tone==='red':s.tone!=='red')));$('#award-results').innerHTML=list.length?list.map(s=>`<article class="award"><div><div class="eyebrow">${s.id} <span aria-hidden="true">/</span> ${s.type}</div><h2>${s.name}</h2><p>${s.description}</p><span class="pill">${s.scope}</span></div><div class="award-aside"><span class="pill ${s.tone}">${s.state}</span><button class="button secondary" data-award="${s.id}">Read funding record ↗</button></div></article>`).join(''):`<div class="empty"><h2>No matching funding records.</h2><p>Try a broader search or a different status.</p></div>`;}
function showCompare(){
 const list=programs.filter(p=>selected.has(p.id));
 $('#main').innerHTML=head('SIDE BY SIDE','Find the meaningful differences.','Compare the available evidence, not just the price tag. Different degree types and cost periods are labeled explicitly.') + (list.length<2?`<div class="empty"><div class="eyebrow">${list.length} PROGRAM${list.length===1?'':'S'} SELECTED</div><h2>Bring two perspectives together.</h2><p>Select at least two programs from Explore programs to compare their research.</p><a class="button" href="#programs">Choose programs ↗</a></div>`:`<div class="notice" style="margin:0 0 22px"><span class="notice-icon">ⓘ</span><div><b>These are different degree categories.</b> CS MS and MBA profiles illustrate program differences; they are not interchangeable options. Annual and first-year tuition references are not total degree costs.</div></div><div class="table-wrap"><table><caption class="sr-only">Comparison of selected master's programs</caption><thead><tr><th scope="col">Research dimension</th>${list.map(p=>`<th scope="col">${p.short}<p class="degree">${p.degree}</p><button class="remove" data-remove="${p.id}">Remove from comparison ×</button></th>`).join('')}</tr></thead><tbody>${[
 ['Category',p=>p.area+' · '+p.kind],['Orientation',p=>p.orientation],['Tuition reference',p=>`<strong>${money(p.tuition)}</strong><p>${p.tuitionLabel} · ${p.period}</p><p>${p.costNote}</p>`],['Other costs',p=>p.costDetail],['Application deadline',p=>p.deadline],['Internships',p=>p.internship],['Faculty & research access',()=> 'Individual professors, specialties and supervision access: not yet verified.'],['Funding',p=>p.funding],['Ranking positions',()=> 'Not yet verified. Publisher, category and edition will be recorded separately.'],['Official sources',p=>`<div class="source-links">${p.sources.map(s=>external(...s)).join('')}</div>`]
 ].map(([label,value])=>`<tr><th scope="row">${label}</th>${list.map(p=>`<td>${value(p)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);
}
function showSources(){ $('#main').innerHTML=head('KNOW WHAT IS BEHIND THE CLAIM','Sources & methodology','Use rankings to discover possibilities. Use primary sources to verify costs, requirements and opportunities. Keep the distinction visible.')+`<div class="source-grid">${sources.map(s=>`<article class="source-card"><div class="source-head"><strong>${s.initials}</strong><span>${s.tag}</span></div><h2>${s.name}</h2><p>${s.text}</p><p class="limit">${s.limit}</p><div class="source-links">${external('Visit source',s.url)}</div></article>`).join('')}</div><div class="bottom-grid"><section class="mini-panel"><div class="eyebrow">COSTS THAT CAN BE COMPARED</div><h3>Keep the year and basis attached.</h3><p>Record tuition, required terms, fees, insurance and living expenses separately. Scholarships reduce net cost only when awarded or modeled as an uncertain scenario. Loans are not scholarships.</p></section><section class="mini-panel"><div class="eyebrow">OPPORTUNITIES WITH EVIDENCE</div><h3>Support is not a placement guarantee.</h3><p>Separate required internships, optional placements and career services. Check the reporting cohort, denominator and international-student outcomes before making claims.</p></section></div><div class="notice"><span class="notice-icon">ⓘ</span><div><b>Verified, prior-year, inferred or unknown.</b> Every finding should retain its source and research date. Missing data never means zero opportunity. <a href="#notes/01-sources%2Fsource-guide.md">Read the full source guide ↗</a></div></div>`;}
function inline(text,base){let s=esc(text);s=s.replace(/\[([^\]]+)\]\(([^)]+)\)/g,(_,label,url)=>{if(/^https:\/\//.test(url))return `<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;if(!url.startsWith('/')&&!url.includes(':')){const parts=base.split('/').slice(0,-1);for(const p of url.split('/')){if(p==='..')parts.pop();else if(p!=='.')parts.push(p);}const file=parts.join('/');if(notes.some(n=>n.path===file))return `<a href="#notes/${encodeURIComponent(file)}" data-note-link>${label}</a>`;}return label;});return s.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');}
function markdown(body,base){const lines=body.split('\n');let html='',inList=false;for(let i=0;i<lines.length;i++){const line=lines[i];if(!/^(- |\d+\. )/.test(line)&&inList){html+='</ul>';inList=false;}if(line.startsWith('|')){const rows=[];while(i<lines.length&&lines[i].startsWith('|'))rows.push(lines[i++]);i--;html+='<div class="table-wrap"><table>';rows.filter(r=>!/^\|[\s:|\-]+\|$/.test(r)).forEach((r,j)=>{html+=j===0?'<thead><tr>':'<tr>';html+=r.split('|').slice(1,-1).map(c=>`<${j===0?'th':'td'}>${inline(c.trim(),base)}</${j===0?'th':'td'}>`).join('');html+=j===0?'</tr></thead><tbody>':'</tr>';});html+='</tbody></table></div>';continue;}const h=line.match(/^(#{1,3}) (.*)/);if(h){html+=`<h${h[1].length}>${inline(h[2],base)}</h${h[1].length}>`;continue;}if(/^(- |\d+\. )/.test(line)){if(!inList){html+='<ul>';inList=true;}html+=`<li>${inline(line.replace(/^(- |\d+\. )/,''),base)}</li>`;}else if(line.trim())html+=`<p>${inline(line,base)}</p>`;}if(inList)html+='</ul>';return html;}
function showNotes(){const note=notes.find(n=>n.path===activeNote)||notes[0];$('#main').innerHTML=head('THE COMPLETE RESEARCH RECORD','Open the notebook.','Read the original findings, scope, evidence rules and reusable dossier template. These documents are the foundation of the collection.')+`<div class="notebook"><nav class="note-list" aria-label="Research documents">${notes.map(n=>`<button data-note="${esc(n.path)}" class="${n.path===note.path?'active':''}" aria-current="${n.path===note.path?'page':'false'}">${esc(n.title)}</button>`).join('')}</nav><article class="document">${markdown(note.body,note.path)}</article></div>`;}
function programDetail(id){const p=programs.find(p=>p.id===id);if(!p)return;$('#dialog-content').innerHTML=`<article class="dossier"><div class="eyebrow">${p.university} / ${p.area}</div><h2 id="dialog-title">${p.degree}</h2><div class="badge-row"><span class="pill">Preliminary research</span><span class="pill">Checked ${checked}</span></div><p>${p.academic}</p><div class="fact-box"><div class="cost-label">${p.tuitionLabel} · ${p.period}</div><strong>${money(p.tuition)} USD</strong><p>${p.costNote}</p><p>${p.costDetail}</p></div><h3>Admissions & timing</h3><p>${p.id==='stanford-mba'?'Round 1: 9 September 2026 (passed as of the research date). Round 2: 6 January 2027. Round 3: 7 April 2027. Confirm the deadline time, timezone and suitable round on the official page.':p.deadline+'. Prerequisites, tests and admissions details need a program-specific check.'}</p><h3>Faculty & academic direction</h3><p>${p.orientation}. Individual faculty specialties and access to supervision have not yet been verified.</p><h3>Internships & career support</h3><p>${p.internship}</p><h3>Scholarships & funding</h3><p>${p.funding}</p><div class="inline-actions">${p.scholarships.map(id=>{const s=scholarships.find(s=>s.id===id);return `<button class="button secondary" data-award="${id}">${s.name}${s.tone==='red'?' · Closed':''} ↗</button>`;}).join('')}</div><h3>What still needs research</h3><ul class="checklist">${['Faculty specializations','Supervision access','Internship placement results','THE / QS / US News positions','2027–28 tuition','Full-degree cost'].map(t=>`<li>${t}<span>NOT YET VERIFIED</span></li>`).join('')}</ul><h3>Follow the sources</h3><div class="source-links">${p.sources.map(s=>external(...s)).join('')}</div><a class="text-link" data-note-link href="#notes/${encodeURIComponent(p.note)}">Read original research note ↗</a></article>`;openDialog();}
function awardDetail(id){const s=scholarships.find(s=>s.id===id);if(!s)return;$('#dialog-content').innerHTML=`<article class="dossier"><div class="eyebrow">${s.id} / ${s.type}</div><h2 id="dialog-title">${s.name}</h2><div class="badge-row"><span class="pill ${s.tone}">${s.state}</span><span class="pill">${s.scope}</span></div><p>${s.description}</p><h3>Eligibility & program scope</h3><p>${s.eligibility}</p><h3>Award coverage</h3><p>${s.amount}. Renewal and stacking rules require verification.</p><h3>Deadline & application</h3><p>${s.deadline}.</p>${s.id==='SCH-002'?'<p>Applicants who already submitted a KHS application must also apply to their Stanford degree by the earlier of the program’s KHS deadline or 1 December 2026.</p>':''}<div class="notice"><div>Checked ${checked}. This record does not establish an individual applicant’s eligibility or award amount.</div></div><h3>Related program research</h3><div class="inline-actions">${programs.filter(p=>p.scholarships.includes(s.id)).map(p=>`<button class="button secondary" data-program="${p.id}">${p.short} · ${p.kind} ↗</button>`).join('')||'<p>No verified program links in the current collection.</p>'}</div><div class="source-links">${external('Official award source',s.url)}</div><a class="text-link" data-note-link href="#notes/${encodeURIComponent(s.note)}">Read original funding record ↗</a></article>`;openDialog();}
function openDialog(){if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0;$('#close-dialog').focus();}
$('#close-dialog').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#detail').close();}});
document.addEventListener('click',e=>{
 const btn=e.target.closest('button,a');if(!btn)return;
 if(btn.hasAttribute('data-area')){area=btn.dataset.area;document.querySelectorAll('[data-area]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.area===area));renderProgramResults();}
 if(btn.hasAttribute('data-reset-programs')){area='All programs';query='';showPrograms();}
 if(btn.dataset.program)programDetail(btn.dataset.program);
 if(btn.dataset.award)awardDetail(btn.dataset.award);
 if(btn.dataset.remove){selected.delete(btn.dataset.remove);saveSelection();showCompare();}
 if(btn.dataset.note)location.hash='notes/'+encodeURIComponent(btn.dataset.note);
 if(btn.hasAttribute('data-note-link'))$('#detail').close();
});
document.addEventListener('change',e=>{if(e.target.dataset.compare){const id=e.target.dataset.compare;e.target.checked?selected.add(id):selected.delete(id);saveSelection();toast(`${selected.size} program${selected.size===1?'':'s'} selected for comparison`);}});
function route(){const [page,doc]=location.hash.slice(1).split('/');if(doc){try{activeNote=decodeURIComponent(doc);}catch{activeNote='README.md';}}const current=['programs','scholarships','compare','sources','notes'].includes(page)?page:'programs';document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===current);if(a.dataset.nav===current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});({programs:showPrograms,scholarships:showAwards,compare:showCompare,sources:showSources,notes:showNotes})[current]();document.title=`${{programs:'Explore programs',scholarships:'Scholarship library',compare:'Compare programs',sources:'Sources & methodology',notes:'Research notebook'}[current]} — Fieldnotes`;window.scrollTo(0,0);}
window.addEventListener('hashchange',()=>{$('#detail').close();route();});route();
